// NewDialogTurnRequest calls the generic DialogTurn builder with application/json body
func NewDialogTurnRequest(server string, body DialogTurnJSONRequestBody) (*http.Request, error) {
	var bodyReader io.Reader
	buf, err := json.Marshal(body)
	if err != nil {
		return nil, err
	}
	bodyReader = bytes.NewReader(buf)
	return NewDialogTurnRequestWithBody(server, "application/json", bodyReader)
}

// NewDialogTurnRequestWithBody constructs an http.Request for the DialogTurn method, with any body, and a specified content type
func NewDialogTurnRequestWithBody(server string, contentType string, body io.Reader) (*http.Request, error) {
	var err error

	serverURL, err := url.Parse(server)
	if err != nil {
		return nil, err
	}

	operationPath := fmt.Sprintf("/v1/dialog/turn")
	if operationPath[0] == '/' {
		operationPath = "." + operationPath
	}

	queryURL, err := serverURL.Parse(operationPath)
	if err != nil {
		return nil, err
	}

	req, err := http.NewRequest(http.MethodPost, queryURL.String(), body)
	if err != nil {
		return nil, err
	}

	req.Header.Add("Content-Type", contentType)

	return req, nil
}

// NewGetHealthRequest constructs an http.Request for the GetHealth method
